contract_clause(contrato_ocs_115_2021, clausula_segunda_vigencia, 'CLÁUSULA SEGUNDA – VIGÊNCIA', 'O presente Contrato terá duração de 46 (quarenta e seis) meses, a contar da data de sua assinatura.').
